import type { Macros } from './recipes';

/**
 * The composition of every recipe, as data.
 *
 * GENERATED by tools/build-recipe-items.ts — edit the recipe's ingredient
 * lines or the override table there, not this file.
 *
 * Each entry lists what goes into the whole recipe in grams, pointing at the
 * food table for composition. Spices and herbs with no stated amount carry
 * no food and contribute nothing: naming the gap beats inventing a weight.
 * The macros beside them are the sum of the items, per serving, which is
 * also what the recipe itself now states.
 */

export interface RecipeItem {
  readonly name: string;
  /** Grams for the whole recipe, not per serving. */
  readonly grams: number;
  /** Food table id, or null when nothing measurable corresponds. */
  readonly food: string | null;
}

export interface RecipeComposition {
  readonly items: readonly RecipeItem[];
  readonly macros: Macros;
}

